# =================================================================== # Hybrid model from Ott's if os.path.exists("./data/bids/limited_energy/derivatives/models/hybrid_model_trace.nc"): idata = az.from_netcdf("./data/bids/limited_energy/derivatives/models/hybrid_model_trace.nc") traces['hybrid_model'] = idata else: # Define the priors: priors = { 'dv_23': bmb.Prior('Normal', mu=0, sigma=2), 'dv_14': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_1': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_2': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_3': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_4': bmb.Prior('Normal', mu=0, sigma=2), 'is_full_energy': bmb.Prior('Normal', mu=0, sigma=2), 'is_low_energy_LC': bmb.Prior('Normal', mu=0, sigma=2), 'is_low_energy_HC': bmb.Prior('Normal', mu=0, sigma=2), 'dv_23|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'dv_14|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_1|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_2|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_3|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_4|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), }
hybrid_model = bmb.Model( "response ~ dv_23 + dv_14 + is_basic_1 + is_basic_2 + is_basic_3 + is_basic_4 + is_full_energy + is_low_energy_LC + is_low_energy_HC + " " + (dv_23 + dv_14 + is_basic_1 + is_basic_2 + is_basic_3 + is_basic_4|vpn)", beh_data, family="bernoulli" ) # Add the idata to the rest: traces['hybrid_model'] = hybrid_model.fit( draws=n_samples, tune=n_warmup, chains=n_chains, target_accept=0.85, idata_kwargs={"log_likelihood": True} ) # Get the predicted responses: hybrid_model.predict(traces['hybrid_model'], kind="response_params", inplace=True)
# Save the trace to file: az.to_netcdf(traces['hybrid_model'], "./data/bids/limited_energy/derivatives/models/hybrid_model_trace.nc")

model_comparison = az.compare(traces)

# Compute the LOO for each model and participants:
loo_results = {}
for model_name, idata in traces.items():
    loo_results[model_name] = az.loo(idata, pointwise=True)
loos_df = pd.DataFrame({
    "vpn": beh_data['vpn'],
    **{model_name: loo_results[model_name].loo_i for model_name in loo_results.keys()}
})
# Sum within subject:
loos_sub = loos_df.groupby('vpn').sum().reset_index()
